const total = os.totalmem();
const free = os.freemem();
const used = total - free;
const memPercent = Math.round((used / total) * 100);
const homedir = os.homedir();
const dlDir = path.join(homedir, 'Downloads');
let pendingFiles = [];
let sourceError = null;

try {
    if (fs.existsSync(dlDir)) {
        pendingFiles = fs.readdirSync(dlDir)
            .filter(name => !name.startsWith('.') && !name.endsWith('.crdownload'))
            .map(name => {
                const fullPath = path.join(dlDir, name);
                const stat = fs.statSync(fullPath);
                return stat.isFile() ? { filename: name, path: fullPath, size_bytes: stat.size, modified_at: stat.mtime.toISOString(), stable: true } : null;
            })
            .filter(Boolean).slice(0, 5);
    }
} catch (err) { sourceError = err.message; }

msg.payload = {
    task_id: `task_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    task_type: 'CLASSIFY_FILE',
    source: 'DAY24_INGESTION',
    input: {
        collected_at: new Date().toISOString(),
        download_dir: dlDir,
        metrics: { mem_percent: memPercent, is_heavy: memPercent > 80 },
        files: pendingFiles,
        source_error: sourceError
    }
};
return msg;

